//! Compatibility with a configuration generated by the Python TUI.

mod common;

use std::fs;
use std::path::{Path, PathBuf};

use common::cli;
use neutron_transport_dd::config::{Config, RunOverrides};
use neutron_transport_dd::core::Runner;
use serde_json::{Value, json};
use tempfile::TempDir;

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/python_tui_config.json")
}

fn read(path: &Path) -> Value {
    serde_json::from_str(&fs::read_to_string(path).expect("read")).expect("json")
}

#[test]
fn python_tui_configuration_loads_with_effective_runtime_values() {
    let config =
        Config::from_json_file_with(fixture(), RunOverrides::default(), None).expect("fixture");

    assert_eq!(config.epsilon, 1e-5);
    assert_eq!(config.max_iter, 2000);
    assert_eq!(config.n, 4);
    assert_eq!(config.n_half, 2);
    assert_eq!(config.ntc, 50);
    assert_eq!(config.mode.as_str(), "eigenvalue");
    assert!(!config.reflex_izq);
    assert!(config.reflex_der);

    assert_eq!(
        config.zone_names,
        Some(vec![
            "REFLECTOR".to_string(),
            "Fuel 1".to_string(),
            "Fuel 2".to_string()
        ])
    );
    // A one-element boundary vector expands to N/2 values, even when the
    // boundary is reflective and the values are unused.
    assert_eq!(config.bound_left, vec![0.0, 0.0]);
    assert_eq!(config.bound_right, vec![0.0, 0.0]);
}

#[test]
fn zone_names_and_tolerances_survive_the_round_trip() {
    let config =
        Config::from_json_file_with(fixture(), RunOverrides::default(), None).expect("fixture");
    let dict = config.as_dict();

    assert_eq!(dict["ZONE_NAMES"], json!(["REFLECTOR", "Fuel 1", "Fuel 2"]));
    assert_eq!(dict["epsilon"], json!(1e-5));
    assert_eq!(dict["max_iter"], json!(2000));

    let restored = Config::from_value_with(&dict, RunOverrides::default(), None).expect("restore");
    assert_eq!(restored.as_dict(), dict);
}

#[test]
fn the_sample_configuration_runs() {
    let config =
        Config::from_json_file_with(fixture(), RunOverrides::default(), None).expect("fixture");
    let result = Runner::new(config).expect("runner").run().expect("run");

    assert!(result.converged);
    assert!(result.k_eff.unwrap() > 0.0);
    assert_eq!(result.scalar_flux.len(), 50);
}

#[test]
fn cli_validate_accepts_the_python_tui_file() {
    let home = TempDir::new().expect("temp");
    let output = cli(home.path(), &["validate", fixture().to_str().unwrap()]);
    assert!(output.status.success(), "{output:?}");
    assert!(String::from_utf8_lossy(&output.stdout).contains("Configuration is valid"));
}

#[test]
fn cli_run_keeps_configuration_metadata_and_honours_json_tolerances() {
    let home = TempDir::new().expect("temp");
    let output_path = home.path().join("out.json");
    let output = cli(
        home.path(),
        &[
            "run",
            "--json",
            fixture().to_str().unwrap(),
            "-o",
            output_path.to_str().unwrap(),
        ],
    );
    assert!(output.status.success(), "{output:?}");

    let payload = read(&output_path);
    let configuration = &payload["runs"][0]["configuration"];
    assert_eq!(configuration["epsilon"], json!(1e-5));
    assert_eq!(configuration["max_iter"], json!(2000));
    assert_eq!(
        configuration["ZONE_NAMES"],
        json!(["REFLECTOR", "Fuel 1", "Fuel 2"])
    );
    assert_eq!(configuration["bound_left"], json!([0.0, 0.0]));
    assert_eq!(
        payload["runs"][0]["scalar_flux"].as_array().unwrap().len(),
        50
    );
    assert!(payload["runs"][0]["k_eff"].as_f64().unwrap() > 0.0);
}

#[test]
fn cli_flags_override_the_json_tolerances() {
    let home = TempDir::new().expect("temp");
    let output_path = home.path().join("out.json");
    let output = cli(
        home.path(),
        &[
            "run",
            "--json",
            fixture().to_str().unwrap(),
            "--epsilon",
            "1e-3",
            "--max-iter",
            "500",
            "-o",
            output_path.to_str().unwrap(),
        ],
    );
    assert!(output.status.success(), "{output:?}");

    let payload = read(&output_path);
    let configuration = &payload["runs"][0]["configuration"];
    assert_eq!(configuration["epsilon"], json!(1e-3));
    assert_eq!(configuration["max_iter"], json!(500));
}

#[test]
fn expansion_preserves_zone_names_and_tolerances() {
    let home = TempDir::new().expect("temp");
    let template = read(&fixture());
    let mut template = template;
    template["SCS"] = json!(["kk", "kk", "kk"]);
    let template_path = home.path().join("template.json");
    fs::write(
        &template_path,
        serde_json::to_string_pretty(&template).unwrap(),
    )
    .expect("write template");

    let inputs = home.path().join("inputs_1d.json");
    let output = cli(
        home.path(),
        &[
            "expand",
            "--json",
            template_path.to_str().unwrap(),
            "--place-holder",
            "kk",
            "0.5",
            "0.7",
            "0.1",
            "-o",
            inputs.to_str().unwrap(),
        ],
    );
    assert!(output.status.success(), "{output:?}");

    let configs = read(&inputs);
    let configs = configs.as_array().expect("array");
    assert_eq!(configs.len(), 3);
    for config in configs {
        assert_eq!(
            config["ZONE_NAMES"],
            json!(["REFLECTOR", "Fuel 1", "Fuel 2"])
        );
        assert_eq!(config["epsilon"], json!(1e-5));
        assert_eq!(config["max_iter"], json!(2000));
    }

    Config::from_value_with(&configs[0], RunOverrides::default(), None)
        .expect("expanded config is valid");
}
